var n=`1048-ayam-goreng`;var a=`world-1048`;var t=`ID`;var s=`southeast-asia`;var r=4;var o=108;var g={en:`Ayam Goreng`,ua:`Аям горенг`};var d={en:`Ayam Goreng is a dish from Indonesia prepared with chicken drumstick, garlic, galangal, lemongrass. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Аям горенг, страва кухні країни Індонезія, яку готують із таких продуктів: куряча гомілка, часник, галангал, лемонграс. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var l=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 70 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 70 хвилин.`,t:[`marinating`],m:70,i:[[`chicken-drumstick`,850,`g`],[`garlic`,5,`clove`],[`galangal`,30,`g`],[`ground-turmeric`,8,`g`],[`ground-coriander`,8,`g`],[`table-salt`,8,`g`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 20 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 20 хвилин до готовності й м’якості.`,t:[`poaching`],m:20,i:[[`water`,470,`ml`],[`lemongrass`,2,`pcs`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 15 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 15 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:15,i:[[`canola-oil`,650,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lime`,2,`pcs`]]}];var m={slug:n,id:a,country:`ID`,region:s,servings:4,minutes:108,title:g,text:d,steps:l};export{t as country,m as default,a as id,o as minutes,s as region,r as servings,n as slug,l as steps,d as text,g as title};